#!/usr/bin/env bash
#
# configure.sh for knb - modernized 2026
# Supports: Linux, macOS, FreeBSD, SunOS, Cygwin
#

function makefile_main()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

default:
	@echo '-+- >> Available targets:'
	@echo '-+- = dynamic (preferred for most systems)'
	@echo '-+- = static'
	@echo '-+- = debug'

dynamic:
	@make -f Makefile.key
	@echo '-+- Making dynamic'
	@make -f Makefile.dynamic

static:
	@make -f Makefile.key
	@echo '-+- Making static'
	@make -f Makefile.static

debug:
	@make -f Makefile.key
	@echo '-+- Making debug'
	@make -f Makefile.debug

release:
	@make -f Makefile.key
	@echo '-+- Making release'
	@make -f Makefile.release

src:
	@echo '-+- Making src'
	@make -f Makefile.src
	
clean:
	@echo '-+- Making clean'
	@make -f Makefile.clean
" > Makefile
}

function makefile_key()
{
echo "#
# Code generated by configure
# 
# Warning! All changes made in this file will be lost!
#

CC = gcc
OUT = key

$TARGET:
	@echo '-+- Making key'
	@echo '-+- Compiling key.c'
	@\$(CC) key.c -o \$(OUT)
	@echo '-+- Generating key.h'
	@./key 
	@echo '-+- key.h ready' " > Makefile.$TARGET
}

# Writes the common header + link recipe start (post-link steps appended next)
function makefile_up()
{
echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#

.SUFFIXES: .c .o

CC = gcc
OUT = $OUT
CFLAGS = $CFLAGS $FLAGS
LFLAGS = $LFLAGS

.c.o:
	@echo '-+- Compiling \$<'
	@\$(CC) -c \$< \$(CFLAGS)

EXE_DEPEND = uf.o \\
cfg.o \\
irc.o \\
sha256.o \\
cmds.o \\
http.o \\
match.o \\
queue.o \\
events.o \\
update.o \\
signals.o \\
validate.o \\
functions.o \\
main.o

$TARGET: key.h \$(EXE_DEPEND)
	@echo '-+- Linking'
	@\$(CC) \$(EXE_DEPEND) -o \$(OUT) \$(CFLAGS) \$(LFLAGS)"  > Makefile.$TARGET
}

# Secondary rules must come AFTER the full main recipe
function makefile_footer()
{
echo "
# key.h is required by validate.c
validate.o: key.h

key.h:
	@make -f Makefile.key
" >> Makefile.$TARGET
}

function makefile_done()
{
	echo "	@echo '-+- Done'" >> Makefile.$TARGET
	makefile_footer
}

function makefile_release()
{
echo "	@echo '-+- Creating release'
	@mkdir knb
	@mkdir knb/cfg-examples
	@mkdir knb/scripts
	@cp ../scripts/* knb/scripts
	@cp ../cfg-examples/* knb/cfg-examples
	@cp ../CHANGELOG knb/CHANGELOG
	@cp ../README knb/README
	@echo -+- Stripping debug information
	@strip \$(OUT) || true
	@if [ -f validate.c ] && [ -f key.h ]; then \\
		echo '-+- Building validator'; \\
		\$(CC) sha256.o -o validator validator.c || true; \\
		if [ -x ./validator ]; then echo '-+- Patching file'; ./validator \$(OUT) || true; fi; \\
	fi
	@cp \$(OUT) knb/\$(OUT)
	@ln -s \$(OUT) knb/knb
	@ln -s cfg-examples/conf-ipv4 knb/conf
	@tar -cf \$(OUT).tar knb
	@rm -fr knb
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" >> Makefile.$TARGET
}

function makefile_world()
{
echo "	@echo -+- Stripping debug information
	@strip \$(OUT) || true
	@if [ -f validate.c ] && [ -f key.h ]; then \\
		echo '-+- Building validator'; \\
		\$(CC) sha256.o -o validator validator.c || true; \\
		if [ -x ./validator ]; then echo '-+- Patching file'; ./validator \$(OUT) || true; fi; \\
	fi
	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../knb
	@ln -s \$(OUT) ../knb" >> Makefile.$TARGET
}

function makefile_deb()
{
echo "	@echo '-+- Building validator (optional)'
	@if [ -f validate.c ] && [ -f key.h ]; then \\
		\$(CC) sha256.o -o validator validator.c || true; \\
		if [ -x ./validator ]; then ./validator \$(OUT) || true; fi; \\
	fi
	@mv \$(OUT) ../\$(OUT)
	@rm -fr ../knb
	@ln -s \$(OUT) ../knb" >> Makefile.$TARGET
}

function makefile_src()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = knb-\$VER-src

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr knb
	@rm -fr *.o Makefile Makefile.* key.h key
	@echo '-+- Creating struct of files'
	@mkdir knb
	@mkdir knb/src
	@mkdir knb/cfg-examples
	@mkdir knb/scripts
	@cp ../scripts/* knb/scripts
	@cp ../cfg-examples/* knb/cfg-examples
	@cp ../src/configure knb/src/configure
	@cp ../src/configure.sh knb/src/configure.sh
	@cp ../src/*.h knb/src
	@cp ../src/*.c knb/src
	@cp ../CHANGELOG knb/CHANGELOG
	@cp ../README knb/README
	@ln -s cfg-examples/conf-ipv4 knb/conf
	@echo '-+- Creating archive'
	@tar -cf \$(OUT).tar knb/
	@rm -fr knb
	@rm -fr \$(OUT)
	@gzip -9 -f \$(OUT).tar
	@mv \$(OUT).tar.gz ../\$(OUT).tar.gz" > Makefile.$TARGET    
}

function makefile_clean()
{
    echo "#
# Code generated by configure
#
# Warning! All changes made in this file will be lost!
#    

OUT = $OUT

$TARGET:
	@echo '-+- Cleaning up'
	@rm -fr knb *.o validator key.h key Makefile Makefile.* ../knb ../\$(OUT)
" > Makefile.$TARGET		
}

function help()
{
    echo "-+-  --with-ipv6          enable IPv6 (default: on except Cygwin)"
    echo "-+-  --without-ipv6       disable IPv6"
    echo "-+-  --without-validator  disable binary validation/protector"
    echo "-+-  --help               this help"
    exit 1
}

function getarg()
{
    IPSET=false
    VALIDSET=false

    VALIDATOR=true
    if [ "$UNAME" = "cygwin" ]; then
        HAVE_IPV6=false
    else
        HAVE_IPV6=true
    fi

    for arg in "$@"; do
        case "$arg" in
            --with-ipv6)
                if [ "$IPSET" = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_IPV6=true; IPSET=true
                ;;
            --without-ipv6)
                if [ "$IPSET" = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                HAVE_IPV6=false; IPSET=true
                ;;
            --without-validator)
                if [ "$VALIDSET" = true ]; then echo "-+- Duplicated $arg"; exit 1; fi
                VALIDATOR=false; VALIDSET=true
                ;;
            --help|-h)
                help
                ;;
            "")
                ;;
            *)
                echo "-+- Unknown option: $arg"
                help
                ;;
        esac
    done
}

function make_echo()
{
    echo "-+- Generating Makefile.$TARGET"    
}

function make_me()
{
    makefile_up
    makefile_world
}

function do_dynamic()
{
    make_echo
    FLAGS=""
    make_me
}

function do_static()
{
    make_echo
    FLAGS="-static"
    make_me
}

function do_debug()
{
    make_echo
    FLAGS="-DDEBUG"
    CFLAGS="$CFLAGS -Wall"
    makefile_up
    makefile_deb
}

function do_release()
{
    FLAGS="-static"
    makefile_up
    makefile_release
}

# ========== main ==========

UNAME=`uname | awk '{ print tolower($1) }'`

case $UNAME in
    sunos) UNAME="sunos";;
    cygwin*) UNAME="cygwin";;
    darwin) UNAME="darwin";;
    freebsd) UNAME="freebsd";;
esac

MACHINE=`uname -m`

VER=`grep KNB_VERSION_STR defines.h | awk '{ print substr($3, 2, length($3)-2) }'`
VER=`echo $VER | tr -d '\r'`
OUT="knb-$VER-$UNAME"
GCC=`gcc -dumpversion 2>/dev/null || echo "unknown"`

LFLAGS=""
CFLAGS="-pipe -O2"

getarg "$@"

if [ "$UNAME" = "sunos" ]; then 
    LFLAGS="-lsocket -lnsl"
    CFLAGS="$CFLAGS -DSUNOS"
elif [ "$UNAME" = "cygwin" ]; then 
    CFLAGS="$CFLAGS -DWINDOWS"
elif [ "$UNAME" = "darwin" ]; then
    CFLAGS="$CFLAGS -D_DARWIN_C_SOURCE"
elif [ "$UNAME" = "freebsd" ]; then
    CFLAGS="$CFLAGS -D_FREEBSD"
fi

if [ "$HAVE_IPV6" = "true" ]; then
    CFLAGS="$CFLAGS -DHAVE_IPV6"
fi

if [ "$VALIDATOR" = "true" ]; then
    CFLAGS="$CFLAGS -DHAVE_VALIDATOR"
fi

echo "-+- Running configure"
echo "-+- Operating system: $UNAME"
echo "-+- Architecture type: $MACHINE"
echo "-+- Gnu C Compiler version: $GCC"
echo -n "-+- IPv6 enabled: "
if [ "$HAVE_IPV6" = "true" ]; then
    echo "yes (./configure --without-ipv6 to turn off)"
else
    echo "no (./configure --with-ipv6 to turn it on)"
fi
echo -n "-+- Validator enabled: "
if [ "$VALIDATOR" = "true" ]; then
    echo "yes (./configure --without-validator to turn off)"
else
    echo "no (binary will be unprotected)"
fi
echo "-+- CFLAGS: $CFLAGS"
echo "-+- LFLAGS: $LFLAGS"
echo "-+- Generating Makefile"
makefile_main
for i in key dynamic static debug release src clean
do
    TARGET="$i"    
    case $TARGET in
	key) makefile_key ;;
	dynamic) do_dynamic ;;
	static) do_static ;;
	debug) do_debug ;;
	release) do_release ;;
	src) makefile_src ;;
	clean) makefile_clean ;;
    esac 
    # key/src/clean have complete recipes already; only add footer for build targets
    case $TARGET in
	dynamic|static|debug|release) makefile_done ;;
	*) true ;;
    esac
done
echo '-+- Configure is done'
